// Parity tests for `src/nin_selector.rs` vs `core/nin_selector.py`.
//
// Follows the same JSON-payload-via-argv pattern established in
// `iran_bridge_prioritizer_parity.rs`: all test data is serialized to one
// JSON blob and passed as `sys.argv[1]`, so no Python source text is ever
// generated by hand-formatting Rust values into Python literals.
//
// Coverage:
// * `is_nin_eligible` over every branch: non-survivable transport,
//   `iran_asn_blocked` rejection, the `NIN_MIN_SCORE` boundary (0.39 vs
//   0.40 vs 0.41), snowflake auto-pass, webtunnel/meek_lite CDN-domain
//   match (via `host`), CDN-ASN match (via `asn`), CDN-domain match via
//   the raw bridge line, the `domain_front_cdn_ok` flag, and the
//   `composite_score`-present-as-explicit-`null` error path (compared as
//   "both sides fail", since Rust surfaces this as `Result::Err` rather
//   than a JSON value — see below).
// * `rescore_for_nin` over the multiplier table, the `round(min(1.0,
//   x*m), 4)` clamp-then-round order (using a value that overshoots 1.0
//   before clamping), descending-sort-with-preserved-ties, and
//   non-mutation of the input.
// * `build_nin_pack`: empty-input short-circuit shape, the full
//   3-file-write path (pack .txt + eligible.json + summary.json) with
//   content compared field-by-field EXCLUDING the wall-clock-dependent
//   `generated_at`/`# Generated:` fields (see the module-level doc
//   comment on `nin_selector.rs` for why those are not directly
//   comparable), and first-seen-wins dedup ordering across the two input
//   paths.
//
// `is_nin_eligible`/`rescore_for_nin` return `Result` on the Rust side
// (see `NinSelectorError`); the Python originals raise an uncaught
// `TypeError` for the equivalent malformed input instead of returning an
// error value. Tests for that path assert Python's subprocess call fails
// (non-zero exit / exception) and Rust's call returns `Err`, rather than
// comparing two JSON values — there is no successful Python return value
// to compare against for that input.

use std::path::Path;
use std::process::Command;

use chrono::Utc;
use serde_json::{json, Map, Value};

use torshield_ir_ultra::nin_selector::{
    build_nin_pack_with_paths, is_nin_eligible, rescore_for_nin,
};

// ─────────────────────────────────────────────────────────────────────────────
// Python helper
// ─────────────────────────────────────────────────────────────────────────────

fn python_executable() -> &'static str {
    if let Ok(path) = std::env::var("PYTHON") {
        return Box::leak(path.into_boxed_str());
    }
    "python3"
}

struct PythonResult {
    success: bool,
    stdout: String,
    stderr: String,
}

fn run_python_script(script: &str, payload: &Value) -> PythonResult {
    let payload_json = serde_json::to_string(payload).expect("payload must serialize");
    let repo_root = env!("CARGO_MANIFEST_DIR");
    let output = Command::new(python_executable())
        .current_dir(repo_root)
        .env("PYTHONPATH", repo_root)
        .arg("-c")
        .arg(script)
        .arg(&payload_json)
        .output()
        .unwrap_or_else(|err| panic!("python helper must execute: {err}"));
    PythonResult {
        success: output.status.success(),
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
    }
}

fn run_python_json(script: &str, payload: &Value) -> Value {
    let result = run_python_script(script, payload);
    assert!(result.success, "python helper failed: {}", result.stderr);
    serde_json::from_str(&result.stdout).unwrap_or_else(|err| {
        panic!(
            "python helper must emit JSON: {err}; stdout={}",
            result.stdout
        )
    })
}

const IS_ELIGIBLE_SCRIPT: &str = r##"
import json, sys
import core.nin_selector as ns

payload = json.loads(sys.argv[1])
result = ns.is_nin_eligible(payload["record"])
print(json.dumps(result))
"##;

const RESCORE_SCRIPT: &str = r##"
import json, sys
import core.nin_selector as ns

payload = json.loads(sys.argv[1])
result = ns.rescore_for_nin(payload["records"])
print(json.dumps(result, sort_keys=True, separators=(",", ":")))
"##;

fn python_is_nin_eligible(record: &Value) -> PythonResult {
    let payload = json!({ "record": record });
    run_python_script(IS_ELIGIBLE_SCRIPT, &payload)
}

fn python_rescore_for_nin(records: &[Value]) -> Value {
    let payload = json!({ "records": records });
    run_python_json(RESCORE_SCRIPT, &payload)
}

// ─────────────────────────────────────────────────────────────────────────────
// Rust-side helpers
// ─────────────────────────────────────────────────────────────────────────────

fn as_map(v: &Value) -> Map<String, Value> {
    v.as_object().unwrap().clone()
}

// ─────────────────────────────────────────────────────────────────────────────
// is_nin_eligible
// ─────────────────────────────────────────────────────────────────────────────

macro_rules! parity_eligible {
    ($name:ident, $record:expr) => {
        #[test]
        fn $name() {
            let record = $record;
            let py = python_is_nin_eligible(&record);
            assert!(py.success, "python call failed unexpectedly: {}", py.stderr);
            let py_value: bool =
                serde_json::from_str(py.stdout.trim()).expect("python must emit a JSON bool");
            let rs_value = is_nin_eligible(&as_map(&record)).expect("rust call must succeed");
            assert_eq!(py_value, rs_value);
        }
    };
}

