#[test]
fn parity_rescore_ties_preserve_original_order() {
    let records = vec![
        json!({"id": 0, "transport": "obfs4", "composite_score": 1.0}),
        json!({"id": 1, "transport": "obfs4", "composite_score": 1.0}),
        json!({"id": 2, "transport": "obfs4", "composite_score": 1.0}),
    ];
    let py = python_rescore_for_nin(&records);
    let rs_maps = rescore_for_nin(&records.iter().map(as_map).collect::<Vec<_>>()).unwrap();
    let rs = Value::Array(rs_maps.into_iter().map(Value::Object).collect());
    assert_eq!(py, rs);
    let py_ids: Vec<i64> = py
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["id"].as_i64().unwrap())
        .collect();
    assert_eq!(py_ids, vec![0, 1, 2]);
}

#[test]
fn parity_rescore_field_preservation() {
    let records = vec![json!({
        "transport": "webtunnel",
        "composite_score": 0.7,
        "custom_field": "must survive",
        "nested": {"a": 1}
    })];
    let py = python_rescore_for_nin(&records);
    let rs_maps = rescore_for_nin(&records.iter().map(as_map).collect::<Vec<_>>()).unwrap();
    let rs = Value::Array(rs_maps.into_iter().map(Value::Object).collect());
    assert_eq!(py, rs);
    assert_eq!(py[0]["custom_field"], json!("must survive"));
}

#[test]
fn rescore_for_nin_does_not_mutate_input_rust_only() {
    let records = vec![as_map(
        &json!({"transport": "snowflake", "composite_score": 0.5}),
    )];
    let before = records.clone();
    let _ = rescore_for_nin(&records).unwrap();
    assert_eq!(records, before);
}

// ─────────────────────────────────────────────────────────────────────────────
// build_nin_pack — full I/O path
// ─────────────────────────────────────────────────────────────────────────────

fn unique_tmp_dir(label: &str) -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "nin_selector_parity_{}_{}_{}",
        label,
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

const BUILD_PACK_SCRIPT: &str = r##"
import json, sys
from pathlib import Path
import core.nin_selector as ns

payload = json.loads(sys.argv[1])
tmp = Path(payload["tmp_dir"])
ns.LATEST_RESULTS_PATH = tmp / "latest.json"
ns.IRAN_RESULTS_PATH = tmp / "iran.json"
ns.EXPORT_DIR = tmp / "export"
ns.DATA_DIR = tmp / "data"
ns.EXPORT_DIR.mkdir(parents=True, exist_ok=True)
ns.DATA_DIR.mkdir(parents=True, exist_ok=True)

ns.LATEST_RESULTS_PATH.write_text(json.dumps(payload["latest"]))
ns.IRAN_RESULTS_PATH.write_text(json.dumps(payload["iran"]))

summary = ns.build_nin_pack()

pack_file = ns.EXPORT_DIR / "iran_cut_pack.txt"
eligible_file = ns.DATA_DIR / "nin_eligible.json"

if pack_file.exists():
    pack_text = pack_file.read_text()
    # Strip the wall-clock-dependent line so the pack file body is comparable.
    pack_lines = [l for l in pack_text.split("\n") if not l.startswith("# Generated:")]
    pack_body = "\n".join(pack_lines)
else:
    # Empty-input short circuit in build_nin_pack() returns before ever
    # writing this file — matches the Rust side's `unwrap_or_default()`.
    pack_body = ""

eligible_json = json.loads(eligible_file.read_text()) if eligible_file.exists() else []

out = {
    "summary_stable_fields": {
        k: v for k, v in summary.items() if k not in ("generated_at", "pack_path")
    },
    "pack_body": pack_body,
    "eligible_json": eligible_json,
}
print(json.dumps(out, sort_keys=True, separators=(",", ":")))
"##;

fn rust_build_pack_normalized(tmp: &Path, latest: &Value, iran: &Value) -> Value {
    std::fs::create_dir_all(tmp).unwrap();
    let latest_path = tmp.join("latest.json");
    let iran_path = tmp.join("iran.json");
    let export_dir = tmp.join("export");
    let data_dir = tmp.join("data");
    std::fs::write(&latest_path, serde_json::to_string(latest).unwrap()).unwrap();
    std::fs::write(&iran_path, serde_json::to_string(iran).unwrap()).unwrap();

    let now = Utc::now();
    let summary = build_nin_pack_with_paths(&latest_path, &iran_path, &export_dir, &data_dir, now)
        .expect("rust build_nin_pack_with_paths must succeed");

    let pack_text =
        std::fs::read_to_string(export_dir.join("iran_cut_pack.txt")).unwrap_or_default();
    let pack_body: String = pack_text
        .split('\n')
        .filter(|l| !l.starts_with("# Generated:"))
        .collect::<Vec<_>>()
        .join("\n");
    let eligible_json: Value = if data_dir.join("nin_eligible.json").exists() {
        serde_json::from_str(&std::fs::read_to_string(data_dir.join("nin_eligible.json")).unwrap())
            .unwrap()
    } else {
        json!([])
    };

    let mut summary_map = summary.as_object().cloned().unwrap_or_default();
    summary_map.remove("generated_at");
    summary_map.remove("pack_path");

    json!({
        "summary_stable_fields": summary_map,
        "pack_body": pack_body,
        "eligible_json": eligible_json,
    })
}

#[test]
fn parity_build_nin_pack_empty_input() {
    let tmp = unique_tmp_dir("empty");
    let latest = json!({"bridges": []});
    let iran = json!({"bridges": []});

    let payload = json!({
        "tmp_dir": tmp.join("py").display().to_string(),
        "latest": latest,
        "iran": iran,
    });
    std::fs::create_dir_all(tmp.join("py")).unwrap();
    let py = run_python_json(BUILD_PACK_SCRIPT, &payload);

    let rs = rust_build_pack_normalized(&tmp.join("rs"), &latest, &iran);

    // Empty-input short circuit returns {"eligible": 0, "total": 0} on
    // BOTH sides (not the full summary shape) — pack/eligible files are
    // never written in that branch on either side.
    assert_eq!(
        py["summary_stable_fields"],
        json!({"eligible": 0, "total": 0})
    );
    assert_eq!(
        rs["summary_stable_fields"],
        json!({"eligible": 0, "total": 0})
    );

    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn parity_build_nin_pack_full_pipeline() {
    let tmp = unique_tmp_dir("full");
    let latest = json!({"bridges": [
        {"line": "snowflake url=https://x abc", "transport": "snowflake", "composite_score": 0.9},
        {"line": "webtunnel 1.2.3.4:443 url=https://y.fastly.net", "transport": "webtunnel", "composite_score": 0.7, "host": "y.fastly.net"},
        {"line": "obfs4 5.6.7.8:443 DEADBEEF", "transport": "obfs4", "composite_score": 0.95},
        {"line": "snowflake url=https://x abc", "transport": "snowflake", "composite_score": 0.1}
    ]});
    let iran = json!({"bridges": [
        {"line": "meek_lite azureedge.net", "transport": "meek_lite", "composite_score": 0.8, "host": "bridge.azureedge.net"}
    ]});

    let payload = json!({
        "tmp_dir": tmp.join("py").display().to_string(),
        "latest": latest,
        "iran": iran,
    });
    std::fs::create_dir_all(tmp.join("py")).unwrap();
    let py = run_python_json(BUILD_PACK_SCRIPT, &payload);
    let rs = rust_build_pack_normalized(&tmp.join("rs"), &latest, &iran);

    assert_eq!(py, rs);

    let _ = std::fs::remove_dir_all(&tmp);
}

#[test]
fn parity_build_nin_pack_dedup_first_seen_wins() {
    let tmp = unique_tmp_dir("dedup");
    // Same "line" key present in both files with different scores;
    // LATEST_RESULTS_PATH is read first, so its version must win.
    let latest = json!({"bridges": [
        {"line": "snowflake url=https://x abc", "transport": "snowflake", "composite_score": 0.9, "source_tag": "latest"}
    ]});
    let iran = json!({"bridges": [
        {"line": "snowflake url=https://x abc", "transport": "snowflake", "composite_score": 0.1, "source_tag": "iran"}
    ]});

    let payload = json!({
        "tmp_dir": tmp.join("py").display().to_string(),
        "latest": latest,
        "iran": iran,
    });
    std::fs::create_dir_all(tmp.join("py")).unwrap();
    let py = run_python_json(BUILD_PACK_SCRIPT, &payload);
    let rs = rust_build_pack_normalized(&tmp.join("rs"), &latest, &iran);

    assert_eq!(py, rs);
    assert_eq!(
        py["eligible_json"][0]["source_tag"],
        json!("latest"),
        "first-seen-wins must prefer LATEST_RESULTS_PATH's version"
    );

    let _ = std::fs::remove_dir_all(&tmp);
}
